     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinEmpresaMensajeria(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(ComInternaPeer::DATABASE_NAME);
        }

        ComInternaPeer::addSelectColumns($criteria);
        $startcol = ComInternaPeer::NUM_HYDRATE_COLUMNS;
        EmpresaMensajeriaPeer::addSelectColumns($criteria);

        $criteria->addJoin(ComInternaPeer::EMPRESA_MENSAJERIA_ID, EmpresaMensajeriaPeer::EMPRESA_MENSAJERIA_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseComInternaPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = ComInternaPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = ComInternaPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {

                $cls = ComInternaPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                ComInternaPeer::addInstanceToPool($obj1, $key1);
            } // if $obj1 already loaded

            $key2 = EmpresaMensajeriaPeer::getPrimaryKeyHashFromRow($row, $startcol);
            if ($key2 !== null) {
                $obj2 = EmpresaMensajeriaPeer::getInstanceFromPool($key2);
                if (!$obj2) {

                    $cls = EmpresaMensajeriaPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    EmpresaMensajeriaPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (ComInterna) to $obj2 (EmpresaMensajeria)
                $obj2->addComInterna($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


