     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinAllExceptIdioma(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        // $criteria->getDbName() will return the same object if not set to another value
        // so == check is okay and faster
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(ComInternaPeer::DATABASE_NAME);
        }

        ComInternaPeer::addSelectColumns($criteria);
        $startcol2 = ComInternaPeer::NUM_HYDRATE_COLUMNS;

        EmpresaMensajeriaPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + EmpresaMensajeriaPeer::NUM_HYDRATE_COLUMNS;

        EstadoComInternaPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + EstadoComInternaPeer::NUM_HYDRATE_COLUMNS;

        PeriodoPeer::addSelectColumns($criteria);
