        $criteria->addJoin(ComInternaPeer::EMPRESA_MENSAJERIA_ID, EmpresaMensajeriaPeer::EMPRESA_MENSAJERIA_ID, $join_behavior);

        $criteria->addJoin(ComInternaPeer::ESTADOCOMINTERNA_ID, EstadoComInternaPeer::ESTADOCOMINTERNA_ID, $join_behavior);

        $criteria->addJoin(ComInternaPeer::PERIODO_ID, PeriodoPeer::PERIODO_ID, $join_behavior);

        $criteria->addJoin(ComInternaPeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID, $join_behavior);

        $criteria->addJoin(ComInternaPeer::TIPOCOMINTERNA_ID, TipoComInternaPeer::TIPOCOMINTERNA_ID, $join_behavior);

