        $criteria->addJoin(ComInternaPeer::ESTADODIGITALIZACION_ID, EstadoDigitalizacionPeer::ESTADODIGITALIZACION_ID, $join_behavior);

        $criteria->addJoin(ComInternaPeer::TIPOFIRMADIGITAL_ID, TipoFirmaDigitalPeer::TIPOFIRMADIGITAL_ID, $join_behavior);

        $criteria->addJoin(ComInternaPeer::PRIORIDADCOM_ID, PrioridadComPeer::PRIORIDADCOM_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseComInternaPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = ComInternaPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = ComInternaPeer::getInstanceFromPool($key1))) {
